export const BODY: string = "\n<p>آپ کا پورٹل 80KB مانگتا ہے۔ 50KB نہیں، 100KB نہیں، بلکہ بالکل 80KB۔ مقررہ سائز والے ٹول مدد نہیں کر سکتے، اور کوالٹی ترتیب کا اندازہ لگانے سے عدد نہیں ملے گا۔</p>\n<p>ہدف فائل سائز کمپریسر یہ مسئلہ حل کرتا ہے۔ آپ بالکل عدد لکھتے ہیں، اور ٹول بہترین کوالٹی تلاش کرتا ہے جو اس سے تھوڑا نیچے آئے۔</p>\n<p>یہ رہنما پورا طریقہ بتاتا ہے، پورٹل کے اصول پڑھنے سے لے کر تیار فائل کی تصدیق تک۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>پورٹل کے اصول احتیاط سے پڑھیں اور بالکل حد لکھ لیں۔ عدد، اکائی، فارمیٹ اور ابعاد کے اصول نوٹ کریں۔</p>\n<p>دستیاب بہترین کوالٹی میں اصل تصویر لیں۔ کیمرے کی تصویر مثالی ہے، چیٹ ایپ سے آگے بھیجی گئی کاپی پہلے سے خراب ہوتی ہے۔</p>\n<p>جانچیں کہ حد زیادہ سے زیادہ ہے یا بالکل سائز ہے۔ زیادہ تر پورٹل زیادہ سے زیادہ بتاتے ہیں، جس کا مطلب ہے کہ عدد سے نیچے کوئی بھی فائل پاس ہو جاتی ہے۔</p>\n<h2 id=\"step-1-open\">مرحلہ 1: ہدف کمپریسر کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/makhsus-size-tak-tasveer-compress-karein/\">Target File Size Compressor</a> کھولیں۔ اکاؤنٹ یا انسٹال کی ضرورت نہیں ہے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی تصویریں مقامی طور پر پروسیس ہوتی ہیں اور کبھی کسی سرور پر اپ لوڈ نہیں ہوتیں۔</p>\n<p>اگر آپ فون پر ہیں تو صفحہ ویسے ہی کام کرتا ہے۔ اپ لوڈ والے حصے پر ٹیپ کریں اور گیلری سے تصویر چنیں۔ اگر آپ اکثر غیر معمولی سائز پر کمپریس کرتے ہیں تو صفحہ بک مارک کر لیں۔</p>\n<h2 id=\"step-2-type-target\">مرحلہ 2: اپنا بالکل ہدف لکھیں</h2>\n<p>پورٹل کے اصولوں والا عدد ہدف والے خانے میں لکھیں۔ اگر پورٹل 80KB کہتا ہے تو 80 لکھیں اور KB چنیں۔</p>\n<p>اکائی احتیاط سے چنیں۔ KB اور MB میں ہزار گنا فرق ہوتا ہے، اور غلط اکائی بہت غلط فائل بناتی ہے۔</p>\n<p>اپ لوڈ سے پہلے عدد دوبارہ جانچیں۔ یہاں ٹائپو پورا رن ضائع کر دیتا ہے، کیونکہ ٹول غلط ہدف کو بھی وفاداری سے حاصل کر لے گا۔</p>\n<h2 id=\"step-3-upload\">مرحلہ 3: اپنی تصویر اپ لوڈ کریں</h2>\n<p>فائل کو صفحے پر گھسیٹ دیں یا براؤز کرنے کے لیے ٹیپ کریں۔ JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں، ہر ایک 25 MB تک۔</p>\n<p>اپنے پاس موجود بہترین کوالٹی والا نسخہ اپ لوڈ کریں۔ 12 میگا پکسل اصل کمپریسر کو چھوٹی کاپی سے کہیں زیادہ مواد دیتا ہے۔</p>\n<p>بیچ کے لیے کئی فائلیں ایک ساتھ چنیں۔ ہر ایک اسی کسٹم ہدف تک کمپریس ہوتی ہے، اور آپ انہیں ZIP کے طور پر ڈاؤن لوڈ کرتے ہیں۔</p>\n<h2 id=\"step-4-format\">مرحلہ 4: آؤٹ پٹ فارمیٹ چنیں</h2>\n<p>تصویروں کے لیے JPG محفوظ پہلے سے طے شدہ انتخاب ہے۔ یہ ہر جگہ قبول ہوتا ہے اور کسی بھی کسٹم سائز پر مؤثر انداز میں کمپریس ہوتا ہے۔</p>\n<p>اگر منزل قبول کرتی ہو اور آپ تیز ترین نتیجہ چاہتے ہوں تو WebP چنیں۔ WebP اسی سائز پر کنارے تھوڑے صاف رکھتا ہے۔</p>\n<p>PNG صرف فلیٹ رنگ، تیز لکیروں یا شفافیت والے گرافکس کے لیے رکھیں۔ PNG میں محفوظ تصویر سخت ہدف تک پہنچنے میں مشکل کرے گی۔</p>\n<h2 id=\"step-5-run\">مرحلہ 5: کمپریشن چلائیں</h2>\n<p>ٹول خودکار بائنری کوالٹی تلاش چلاتا ہے۔ یہ کوالٹی سطحیں آزماتا ہے جب تک وہ سب سے اونچی سطح نہ مل جائے جو آپ کے ہدف سے نیچے فٹ ہو۔</p>\n<p>آپ کو کوالٹی فیصد چننے کی ضرورت نہیں ہے۔ تلاش آپ کی مخصوص تصویر کے لیے بہترین عدد ڈھونڈتی ہے۔</p>\n<p>اس تصدیق کو تلاش کریں کہ ہدف حاصل ہو گیا۔ خلاصہ ہدف، حاصل شدہ سائز اور یہ دکھاتا ہے کہ ہر فائل پاس ہوئی یا نہیں۔</p>\n<h2 id=\"step-6-preview\">مرحلہ 6: نتیجہ احتیاط سے پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے کمپریس شدہ تصویر مکمل سائز میں پیش نظارہ دیکھیں۔ چھوٹا تھمب نیل وہ مسائل چھپاتا ہے جو مکمل سائز پر واضح ہوتے ہیں۔</p>\n<p>پہلے باریک تفصیل جانچیں۔ چہرے، متن اور کنارے سب سے پہلے نرم ہوتے ہیں جب ہدف سخت ہو۔</p>\n<p>اگر موازنے کا منظر دستیاب ہو تو اسے استعمال کریں۔ اصل اور کمپریس شدہ کاپی ساتھ ساتھ دیکھنے سے چھوٹا نقصان آسانی سے نظر آ جاتا ہے۔</p>\n<h2 id=\"step-7-download\">مرحلہ 7: ڈاؤن لوڈ کریں اور تصدیق کریں</h2>\n<p>فائل ڈاؤن لوڈ کریں۔ اس کا نام کسٹم ہدف ظاہر کرے گا، اس لیے یہ اصل سے الجھے گی نہیں۔</p>\n<p>اپنے آلے پر فائل سائز جانچیں۔ یہ آپ کے ہدف سے تھوڑا نیچے پڑھنا چاہیے، گول کرنے کے لیے چھوٹے حفاظتی مارجن کے ساتھ۔</p>\n<p>یقین کریں کہ فارمیٹ پورٹل کے اصولوں سے میل کھاتا ہے۔ غلط فارمیٹ میں بہترین فائل بھی اپ لوڈ میں ناکام ہوتی ہے۔</p>\n<h2 id=\"fixing-misses\">چھوٹا ہوا ہدف ٹھیک کرنا</h2>\n<p>ہدف چھوٹنے کی عام طور پر تین وجوہات میں سے ایک ہوتی ہے۔ فارمیٹ غلط ہے، ابعاد بند ہیں یا ہدف واقعی ناممکن ہے۔</p>\n<p>پہلے آؤٹ پٹ فارمیٹ JPG کریں۔ PNG فارمیٹ میں تصویریں اکثر سخت ہدف تک بالکل نہیں پہنچ سکتیں۔</p>\n<p>دوسرے، ابعاد اسکیلنگ کی اجازت دیں۔ ٹول پکسل سائز قدم بہ قدم کم کرتا ہے، اور چھوٹی کمی اکثر ہدف کھول دیتی ہے۔</p>\n<h2 id=\"batch-exact\">ایک بیچ کو بالکل سائز تک کمپریس کرنا</h2>\n<p>کئی پورٹلوں کو ایک ہی غیر معمولی سائز پر کئی فائلیں چاہییں ہوتی ہیں۔ 80KB پر تصویر اور دستخط دونوں ایک عام جوڑا ہے۔</p>\n<p>تمام فائلیں ایک بیچ میں اسی ہدف کے ساتھ شامل کریں۔ ہر فائل کے لیے الگ الگ بہترین کوالٹی تلاش کی جاتی ہے جو فٹ ہو۔</p>\n<p>بیچ مکمل ہونے کے بعد خلاصہ جانچیں۔ یہ دکھاتا ہے کہ کون سی فائلیں ہدف پر پہنچیں اور کون سی چھوٹ گئیں۔</p>\n<h2 id=\"changing-target\">کمپریشن کے بعد ہدف بدلنا</h2>\n<p>آپ فائلیں دوبارہ اپ لوڈ کیے بغیر ہدف بدل سکتے ہیں۔ نیا عدد لکھیں اور انہی تصویروں پر تلاش دوبارہ چلائیں۔</p>\n<p>یہ اس وقت مفید ہے جب پورٹل کے اصول بدل جائیں۔ کل 80KB مانگنے والا فارم آج 120KB مانگ سکتا ہے، اور تازہ رن سیکنڈوں میں ہوتا ہے۔</p>\n<p>ہمیشہ اصل فائلوں سے دوبارہ چلائیں، کمپریس شدہ کاپیوں سے نہیں۔ کمپریشن کا ہر مرحلہ نقصان جوڑتا ہے، اس لیے تازہ شروع کریں۔</p>\n<h2 id=\"phone-workflow\">ورک فلو: اپنے فون پر</h2>\n<p>موبائل براؤزر میں ٹول کھولیں اور اپ لوڈ والے حصے پر ٹیپ کریں۔ گیلری سے اصل تصویر چنیں۔</p>\n<p>چھوٹے کی بورڈ پر ہدف احتیاط سے لکھیں۔ غلط لکھا عدد فون پر سب سے عام غلطی ہے، اس لیے دوبارہ جانچیں۔</p>\n<p>آئی فون کی تصویریں HEIC فائلیں ہو سکتی ہیں۔ انہیں سیدھا اپ لوڈ کریں، ٹول کمپریشن کے دوران تبدیلی سنبھال لیتا ہے۔</p>\n<h2 id=\"reading-portal-rules\">پورٹل کے اصول چیک لسٹ کی طرح پڑھنا</h2>\n<p>پورٹل کے اصول ہدایات کے لمبے صفحوں میں چھپے ہوتے ہیں۔ انہیں چیک لسٹ کی طرح پڑھیں، اہم عدد نکال کر۔</p>\n<p>چار حقائق نکالیں: زیادہ سے زیادہ سائز، اکائی، قبول شدہ فارمیٹ اور مطلوبہ ابعاد۔ انہیں ایک لائن میں لکھیں۔</p>\n<p>شروع کرنے سے پہلے اس لائن کو ٹول کی ترتیبات سے ملائیں۔ یہاں فرق مسترد شدہ اپ لوڈ کی سب سے عام وجہ ہے۔</p>\n<h2 id=\"odd-targets\">عجیب ہدف: 80KB، 120KB، 150KB</h2>\n<p>عجیب ہدف عام ہیں۔ پورٹل اپنی اسٹوریج وجوہات سے 80KB یا 150KB جیسے عدد چنتے ہیں، اور مقررہ ٹول انہیں پورا نہیں کر سکتے۔</p>\n<p>80KB پورٹریٹ 50KB والے سے نمایاں طور پر زیادہ تفصیل رکھتا ہے۔ بال اور کپڑا بہتر بچتے ہیں، اور چہرہ زیادہ قدرتی لگتا ہے۔</p>\n<p>150KB بلاگ تصویر 100KB اور 200KB معیار کے درمیان بیٹھتی ہے۔ یہ غیر معمولی بجٹ والی تھیم کے لیے معقول درمیانی راستہ ہے۔</p>\n<h2 id=\"verifying-bytes\">نتیجہ بالکل بائٹ میں تصدیق کرنا</h2>\n<p>آلات فائل سائز پورے کلو بائٹ میں گول کر کے دکھاتے ہیں، جو بالکل بائٹ گنتی چھپاتا ہے۔ 80KB دکھائی دینے والی فائل دراصل 80.4KB ہو سکتی ہے۔</p>\n<p>پورٹل بالکل بائٹ جانچتے ہیں۔ آپ کے فون پر ٹھیک لگنے والی فائل چند سو بائٹ سے پورٹل پر ناکام ہو سکتی ہے۔</p>\n<p>اپنے آلے کی بجائے ٹول کی اپنی پڑھت پر بھروسا کریں۔ ٹول بالکل بائٹ گنتی ناپتا ہے اور ہدف سے تھوڑا نیچے ہدف رکھتا ہے۔</p>\n<h2 id=\"signature-exact\">بالکل KB سائز پر دستخط</h2>\n<p>دستخط بالکل ہدف پر خوبصورتی سے کمپریس ہوتے ہیں۔ دستخط زیادہ تر سفید جگہ ہوتا ہے، اس لیے سخت ہدف بھی اسے صاف دکھاتا ہے۔</p>\n<p>دستخط سیدھا اسکین کریں اور سخت کراپ کریں۔ خالی مارجن ہدف بجٹ کو خالی کاغذ پر ضائع کرتے ہیں۔</p>\n<p>سفید کاغذ پر گہرا قلم استعمال کریں۔ ہلکے دستخط کمپریشن میں نرم ہو جاتے ہیں، جبکہ گہری سیاہی کسی بھی سائز پر تیز رہتی ہے۔</p>\n<h2 id=\"documents-exact\">بالکل KB سائز پر دستاویزات</h2>\n<p>دستاویزات میں متن، مہریں اور کبھی چھوٹی تصویر ملے ہوتے ہیں۔ ہر جز کمپریشن میں مختلف برتاؤ کرتا ہے، جس سے بالکل ہدف مشکل ہو جاتا ہے۔</p>\n<p>بہترین توازن کے لیے 300 DPI پر اسکین کریں۔ اونچی ریزولوشن بڑی فائلیں بناتی ہے، جبکہ کم ریزولوشن متن دھندلا کر دیتی ہے۔</p>\n<p>کمپریشن کے بعد سب سے چھوٹا متن پیش نظارہ دیکھیں۔ رجسٹریشن نمبر، تاریخیں اور فوٹ نوٹ سب سے پہلے متاثر ہوتے ہیں۔</p>\n<h2 id=\"retry-strategy\">چھوٹے ہدف کے لیے دوبارہ آزمانے کی حکمت عملی</h2>\n<p>جب ہدف چھوٹ جائے تو ایک وقت میں ایک چیز بدلیں۔ سب کچھ ایک ساتھ بدلنے سے یہ چھپ جاتا ہے کہ کون سی اصلاح کام آئی۔</p>\n<p>پہلے فارمیٹ JPG پر بدلیں۔ یہ اکیلی تبدیلی زیادہ تر چھوٹ ٹھیک کر دیتی ہے، کیونکہ PNG عام مجرم ہوتا ہے۔</p>\n<p>دوسرے، ابعاد اسکیلنگ کی اجازت دیں۔ چھوٹی کمی اکثر ہدف کھول دیتی ہے، بغیر نظر آنے والے نقصان کے۔</p>\n<h2 id=\"keeping-records\">بالکل ہدف کا ریکارڈ رکھنا</h2>\n<p>بالکل ہدف بھولنا آسان ہے۔ پچھلے مہینے 80KB مانگنے والا پورٹل دوبارہ 80KB مانگے گا، اور آپ کو عدد یاد نہیں رہے گا۔</p>\n<p>پورٹلوں کے ساتھ ہدف کی مختصر فہرست رکھیں۔ visa portal 80KB JPG جیسی نوٹ ہر بار اصول دوبارہ پڑھنے سے بچاتی ہے۔</p>\n<p>کمپریس شدہ فائلیں اس درخواست کے ساتھ محفوظ کریں جس سے وہ تعلق رکھتی ہیں۔ visa-photo-80kb.jpg نام کی فائل خود بتاتی ہے۔</p>\n<h2 id=\"final-check-exact\">جمع کرانے سے پہلے آخری جانچ</h2>\n<p>یقین کریں کہ فائل سائز آپ کے آلے پر آپ کے ہدف سے تھوڑا نیچے پڑھتا ہے۔ حد سے نیچے ٹول کا چھوڑا ہوا چھوٹا حفاظتی مارجن تلاش کریں۔</p>\n<p>یقین کریں کہ فارمیٹ اور ابعاد پورٹل کے اصولوں سے میل کھاتے ہیں۔ غلط فارمیٹ میں بہترین سائز بھی اپ لوڈ میں ناکام ہوتا ہے، اس لیے تینوں عدد ساتھ جانچیں۔</p>\n<p>کسٹم ہدف کی مکمل رہنما <a href=\"/ur/blog/makhsus-size-tak-tasveer-compress-karein-rehnumai/\">Target File Size Compressor: Complete Guide</a> میں پڑھیں۔ تلاش کی گہرائی کے لیے <a href=\"/ur/blog/exact-kb-ke-liye-binary-quality-search/\">Exact KB Targets: Binary Quality Search Explained</a> دیکھیں۔ اگر مقررہ سائز سوٹ کرے تو <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">100KB کمپریسر</a> سب سے عام حد پوری کرتا ہے۔</p>\n";

